    #region Load
    private async Task LoadPosts()
    {
        _isLoading = true; StateHasChanged();
        try
        {
            var apiUrl = PN_PublicVariables.Url_Backend + "/ThongBao/V1/GetNhatKyHoatDongByAdmin";
            var client = HttpClientFactory.CreateClient();
            var resp   = await client.PostAsJsonAsync(apiUrl, new { matruongbo = _maTruongBo, ngay = "" });
            if (resp.IsSuccessStatusCode)
            {
                var json = await resp.Content.ReadAsStringAsync();
                using var doc = JsonDocument.Parse(json);
                var root = doc.RootElement;
                if (root.TryGetProperty("success", out var s) && s.GetBoolean() &&
                    root.TryGetProperty("stringdata", out var data) &&
                    data.ValueKind == JsonValueKind.Array)
                    _allPosts = ParsePosts(data);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[HDHN] LoadPosts: {ex.Message}");
            await ShowToast("Lỗi tải dữ liệu!", "error");
        }
        finally { _isLoading = false; StateHasChanged(); }
    }

    private List<PostItem> ParsePosts(JsonElement data)
    {
        var list = new List<PostItem>();
        foreach (var el in data.EnumerateArray())
        {
            try
            {
                var p = new PostItem
                {
                    IdNhatKy     = el.TryGetProperty("id_nhatky",      out var id) ? id.GetInt32()    : 0,
                    MaGiaoVienSo = el.TryGetProperty("ma_giaovien_so", out var ms) ? ms.GetString()??""  : "",
                    TenGiaoVien  = el.TryGetProperty("ten_giaovien",   out var tg) ? tg.GetString()??""  : "",
                    IsTrangThai  = el.TryGetProperty("is_trangthai",   out var ts) ? ts.GetInt32()    : 1,
                };
                if (el.TryGetProperty("ngaytao", out var ng) && DateTime.TryParse(ng.GetString(), out var dt))
                    p.NgayTao = dt;

                if (el.TryGetProperty("chitiet_nhatky", out var cd) && cd.ValueKind == JsonValueKind.Array)
                    foreach (var item in cd.EnumerateArray())
                    {
                        p.TieuDe  = item.TryGetProperty("tieude",  out var t) ? t.GetString() ?? "" : "";
                        p.NoiDung = item.TryGetProperty("noidung", out var n) ? n.GetString() ?? "" : "";
                        if (item.TryGetProperty("tepdinhkem", out var tk) && tk.ValueKind == JsonValueKind.Array)
                            foreach (var u in tk.EnumerateArray())
                                if (!string.IsNullOrEmpty(u.GetString())) p.TepDinhKem.Add(u.GetString()!);
                        break;
                    }

                if (el.TryGetProperty("tuong_tac", out var tt) && tt.ValueKind == JsonValueKind.Array)
                    foreach (var grp in tt.EnumerateArray())
                    {
                        if (grp.TryGetProperty("Like", out var likes) && likes.ValueKind == JsonValueKind.Array)
                            foreach (var lk in likes.EnumerateArray())
                                p.Likes.Add(new LikeItem {
                                    MaSo   = lk.TryGetProperty("maso",   out var m)  ? m.GetString()??""   : "",
                                    HoTen  = lk.TryGetProperty("hoten",  out var h)  ? h.GetString()??""   : "",
                                    IsLike = lk.TryGetProperty("isLike", out var il) && il.ValueKind != JsonValueKind.Null && il.GetBoolean()
                                });
                        if (grp.TryGetProperty("Comment", out var cmts) && cmts.ValueKind == JsonValueKind.Array)
                            foreach (var c in cmts.EnumerateArray())
                                p.Comments.Add(new CommentItem {
                                    MaSo     = c.TryGetProperty("maso",             out var cm) ? cm.GetString()??""  : "",
                                    HoTen    = c.TryGetProperty("hoten",            out var ch) ? ch.GetString()??""  : "",
                                    NoiDung  = c.TryGetProperty("commentContent",   out var cc) ? cc.GetString()??""  : "",
                                    ThoiGian = c.TryGetProperty("thoidiemtuongtac", out var ct) ? ct.GetString()??""  : ""
                                });
                    }
                list.Add(p);
            }
            catch (Exception ex) { Console.WriteLine($"[HDHN] ParsePost: {ex.Message}"); }
        }
        return list.OrderByDescending(p => p.NgayTao).ToList();
    }
    #endregion

    #region CRUD
    private async Task SubmitPost()
    {
        if (string.IsNullOrWhiteSpace(_newContent)) return;
        _isSubmitting = true; StateHasChanged();
        try
        {
            var urls   = _uploadFiles.Where(f => !string.IsNullOrEmpty(f.Url)).Select(f => f.Url!).ToList();
            var client = HttpClientFactory.CreateClient();
            string apiUrl;
            object body;
            if (_isEditMode)
            {
                apiUrl = PN_PublicVariables.Url_Backend + "/ThongBao/V1/UpdateNhatKyHoatDong_URL";
                body   = new { matruongbo = _maTruongBo, id_nhatky = _editingId, tieude = _newTitle, noidung = _newContent, tepdinhkem = urls };
            }
            else
            {
                apiUrl = PN_PublicVariables.Url_Backend + "/ThongBao/V1/AddNhatKyHoatDong_URL";
                body   = new { matruongbo = _maTruongBo, nguoigui = _maUser, tieude = _newTitle, noidung = _newContent, tepdinhkem = urls };
            }
            var resp = await client.PostAsJsonAsync(apiUrl, body);
            if (resp.IsSuccessStatusCode)
            {
                var json = await resp.Content.ReadAsStringAsync();
                using var doc = JsonDocument.Parse(json);
                if (doc.RootElement.TryGetProperty("success", out var ss) && ss.GetBoolean())
                {
                    await ShowToast(_isEditMode ? "Cập nhật bài thành công!" : "Đăng bài thành công!", "success");
                    ResetForm();
                    await Task.Delay(600);
                    await LoadPosts();
                    return;
                }
            }
            await ShowToast("Có lỗi xảy ra, vui lòng thử lại!", "error");
        }
        catch (Exception ex) { Console.WriteLine($"[HDHN] Submit: {ex.Message}"); await ShowToast("Lỗi kết nối!", "error"); }
        finally { _isSubmitting = false; StateHasChanged(); }
    }

    private void StartEdit(PostItem post)
    {
        _openMenuId = null; _isEditMode = true; _editingId = post.IdNhatKy;
        _newTitle = post.TieuDe; _newContent = post.NoiDung;
        _uploadFiles.Clear();
        foreach (var url in post.TepDinhKem)
            _uploadFiles.Add(new UploadItem { Url = url, PreviewUrl = url, FileName = url.Split('/').LastOrDefault()??"file", Type = IsVideoUrl(url)?"video":"image", IsUploaded = true });
        StateHasChanged();
        _ = JS.InvokeVoidAsync("eval", "document.getElementById('create-post')?.scrollIntoView({behavior:'smooth'})");
    }

    private void CancelEdit() { ResetForm(); StateHasChanged(); }

    private void ResetForm() { _isEditMode = false; _editingId = 0; _newTitle = ""; _newContent = ""; _uploadFiles.Clear(); }

    private void AskDelete(PostItem post) { _openMenuId = null; _deleteTarget = post; StateHasChanged(); }
    private void CancelDelete() { _deleteTarget = null; StateHasChanged(); }

    private async Task ConfirmDelete()
    {
        if (_deleteTarget == null) return;
        var target = _deleteTarget; _deleteTarget = null;
        _isSubmitting = true; StateHasChanged();
        try
        {
            var client = HttpClientFactory.CreateClient();
            var resp   = await client.PostAsJsonAsync(
                PN_PublicVariables.Url_Backend + "/ThongBao/V1/DeleteNhatKyHoatDong",
                new { matruongbo = _maTruongBo, id_nhatky = target.IdNhatKy });
            if (resp.IsSuccessStatusCode) { _allPosts.RemoveAll(p => p.IdNhatKy == target.IdNhatKy); await ShowToast("Đã xóa bài viết!", "success"); }
            else await ShowToast("Xóa thất bại!", "error");
        }
        catch (Exception ex) { Console.WriteLine($"[HDHN] Delete: {ex.Message}"); await ShowToast("Lỗi kết nối!", "error"); }
        finally { _isSubmitting = false; StateHasChanged(); }
    }

    private async Task ApprovePost(PostItem post)
    {
        _openMenuId = null; _isLoading = true; StateHasChanged();
        try
        {
            var client = HttpClientFactory.CreateClient();
            var resp   = await client.PostAsJsonAsync(
                PN_PublicVariables.Url_Backend + "/ThongBao/V1/DuyetNhatKyHoatDong",
                new { matruongbo = _maTruongBo, id_nhatky = post.IdNhatKy });
            if (resp.IsSuccessStatusCode)
            {
                post.IsTrangThai = 1;
                if (_activeTab == "pending") SwitchTab("approved");
                await ShowToast("Đã duyệt bài viết!", "success");
            }
            else await ShowToast("Duyệt thất bại!", "error");
        }
        catch (Exception ex) { Console.WriteLine($"[HDHN] Approve: {ex.Message}"); await ShowToast("Lỗi kết nối!", "error"); }
        finally { _isLoading = false; StateHasChanged(); }
    }
