    #region Interactions
    private async Task ToggleLike(PostItem post)
    {
        var existing = post.Likes.FirstOrDefault(l => l.MaSo == _maUser);
        var wasLiked = existing?.IsLike ?? false;
        if (existing != null) existing.IsLike = !wasLiked;
        else post.Likes.Add(new LikeItem { MaSo = _maUser, HoTen = _userName, IsLike = true });
        StateHasChanged();
        try
        {
            var client = HttpClientFactory.CreateClient();
            await client.PostAsJsonAsync(
                PN_PublicVariables.Url_Backend + "/ThongBao/V1/TuongTacNhatKyHoatDong",
                new { matruongbo = _maTruongBo, ma_so = _maUser, ho_ten = _userName,
                      id_nhatky = post.IdNhatKy, likePost = wasLiked ? 0 : 1,
                      commentPost = "", thoiluongTuongtac = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") });
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[HDHN] Like: {ex.Message}");
            if (existing != null) existing.IsLike = wasLiked;
            StateHasChanged();
        }
    }

    private void ToggleComments(PostItem post) { post.ShowComments = !post.ShowComments; StateHasChanged(); }

    private async Task PostComment(PostItem post)
    {
        if (string.IsNullOrWhiteSpace(post.NewComment)) return;
        var text = post.NewComment; post.NewComment = "";
        post.Comments.Add(new CommentItem { MaSo = _maUser, HoTen = _userName, NoiDung = text, ThoiGian = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") });
        StateHasChanged();
        try
        {
            var client = HttpClientFactory.CreateClient();
            await client.PostAsJsonAsync(
                PN_PublicVariables.Url_Backend + "/ThongBao/V1/TuongTacNhatKyHoatDong",
                new { matruongbo = _maTruongBo, ma_so = _maUser, ho_ten = _userName,
                      id_nhatky = post.IdNhatKy, likePost = 0,
                      commentPost = text, thoiluongTuongtac = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") });
        }
        catch (Exception ex) { Console.WriteLine($"[HDHN] Comment: {ex.Message}"); }
    }

    private async Task HandleCommentKey(KeyboardEventArgs e, PostItem post)
    { if (e.Key == "Enter") await PostComment(post); }
