    #region File Upload
    private async Task HandleFileSelected(InputFileChangeEventArgs e)
    {
        const long MaxSize = 15 * 1024 * 1024;
        foreach (var file in e.GetMultipleFiles(10))
        {
            if (file.Size > MaxSize) { await ShowToast($"'{file.Name}' quá lớn (tối đa 15MB)!", "warning"); continue; }
            byte[] data;
            try { using var ms = new System.IO.MemoryStream(); await file.OpenReadStream(MaxSize).CopyToAsync(ms); data = ms.ToArray(); }
            catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); continue; }

            var type    = file.ContentType.StartsWith("image/") ? "image" : file.ContentType.StartsWith("video/") ? "video" : "file";
            var preview = (type == "image" && data.Length < 5*1024*1024) ? $"data:{file.ContentType};base64,{Convert.ToBase64String(data)}" : "";
            var item    = new UploadItem { FileName = file.Name, FileSize = FormatSize(file.Size), Type = type, PreviewUrl = preview, ContentType = file.ContentType, Data = data };
            _uploadFiles.Add(item); StateHasChanged();
            await UploadSingle(item);
        }
    }

    private async Task UploadSingle(UploadItem item)
    {
        item.IsUploading = true; _isUploading = true; StateHasChanged();
        try
        {
            var client  = HttpClientFactory.CreateClient();
            var content = new MultipartFormDataContent();
            var bc      = new ByteArrayContent(item.Data ?? Array.Empty<byte>());
            bc.Headers.ContentType = new MediaTypeHeaderValue(item.ContentType);
            content.Add(bc, "file", item.FileName);
            var resp = await client.PostAsync($"https://nhatkyhoatdong.titkul.edu.vn/upload/media/{_maTruongBo}", content);
            if (resp.IsSuccessStatusCode)
            {
                var json = await resp.Content.ReadAsStringAsync();
                using var doc = JsonDocument.Parse(json);
                var root = doc.RootElement;
                if (root.TryGetProperty("error", out var er) && er.GetInt32() == 0 &&
                    root.TryGetProperty("data",  out var d)  &&
                    d.TryGetProperty("urls", out var urls)   &&
                    urls.ValueKind == JsonValueKind.Array && urls.GetArrayLength() > 0)
                { item.Url = urls[0].GetString() ?? ""; item.IsUploaded = true; }
                else await ShowToast($"Upload '{item.FileName}' thất bại!", "error");
            }
            else await ShowToast($"Upload lỗi HTTP {(int)resp.StatusCode}!", "error");
        }
        catch (Exception ex) { Console.WriteLine($"[HDHN] Upload: {ex.Message}"); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { item.IsUploading = false; _isUploading = _uploadFiles.Any(f => f.IsUploading); StateHasChanged(); }
    }

    private void RemoveUploadFile(UploadItem item) { _uploadFiles.Remove(item); StateHasChanged(); }
    private void ClearFiles() { _uploadFiles.Clear(); StateHasChanged(); }
    #endregion

    #region UI Helpers
