    };

    private void OpenViewer(PostItem post, int idx) { _viewerPost = post; _viewerIndex = idx; StateHasChanged(); }
    private void CloseViewer()  { _viewerPost = null; StateHasChanged(); }
    private void ViewerPrev()   { if (_viewerIndex > 0) _viewerIndex--; StateHasChanged(); }
    private void ViewerNext()
    {
        if (_viewerPost?.TepDinhKem != null && _viewerIndex < _viewerPost.TepDinhKem.Count - 1) _viewerIndex++;
        StateHasChanged();
    }

    private async Task FocusCreatePost()
        => await JS.InvokeVoidAsync("eval", "document.getElementById('create-post')?.scrollIntoView({behavior:'smooth'})");

    private string FormatTime(DateTime dt)
    {
        var diff = DateTime.Now - dt;
        if (diff.TotalMinutes < 1)  return "Vừa xong";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} phút trước";
        if (diff.TotalHours < 24)   return $"{(int)diff.TotalHours} giờ trước";
        if (diff.TotalDays < 7)     return $"{(int)diff.TotalDays} ngày trước";
        return dt.ToString("dd/MM/yyyy HH:mm");
    }
    private string FormatTime(string s) => DateTime.TryParse(s, out var dt) ? FormatTime(dt) : s;

    private string GetInitials(string? name)
    {
        if (string.IsNullOrWhiteSpace(name)) return "?";
        var parts = name.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length >= 2) return $"{parts[0][0]}{parts[^1][0]}".ToUpper();
        return name.Length >= 2 ? name[..2].ToUpper() : name.ToUpper();
    }

    /// <summary>
    /// Lấy URL ảnh đại diện giáo viên từ hệ thống face.titkul.com.
    /// Pattern giống TH_QuanLyThongTinNhanSu: {maTruongBo}/{maSo}.jpg
    /// Nếu không có maTruongBo hoặc maSo → trả về ảnh mặc định.
    /// </summary>
    private string GetAvatarUrl(string? maSo)
    {
        if (string.IsNullOrWhiteSpace(_maTruongBo) || string.IsNullOrWhiteSpace(maSo))
            return "../image/avtmacdinh.jpg";
        return $"https://face.titkul.com/ImageFace/{_maTruongBo}/{maSo}.jpg";
    }

    private static readonly string[] _pal = { "#3b82f6","#8b5cf6","#ec4899","#10b981","#f59e0b","#ef4444","#06b6d4","#6366f1","#84cc16","#f97316" };
    private string GetAvatarColor(string? name) => string.IsNullOrEmpty(name) ? _pal[0] : _pal[Math.Abs(name.GetHashCode()) % _pal.Length];

    private static bool IsVideoUrl(string url) =>
        url.Contains(".mp4", StringComparison.OrdinalIgnoreCase) ||
        url.Contains(".mov", StringComparison.OrdinalIgnoreCase) ||
        url.Contains(".avi", StringComparison.OrdinalIgnoreCase);

    private static string FormatSize(long b)
    {
        if (b < 1024)        return $"{b} B";
        if (b < 1024 * 1024) return $"{b / 1024.0:F1} KB";
        return $"{b / (1024.0 * 1024):F1} MB";
    }

    private async Task ShowToast(string msg, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMsg = msg; _toastType = type; _toastVisible = true;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastVisible = false; StateHasChanged(); }
        catch (TaskCanceledException) { }
    }
